tool_input.command:
grep -rl "onnx_bytes" runs/*/metrics.json 2>/dev/null | tail -3
for f in $(grep -rl "onnx_bytes" runs/*/metrics.json 2>/dev/null | tail -3); do echo "== $f =="; python3 -c "
import json
d=json.load(open('$f'))
def find(o,path=''):
    if isinstance(o,dict):
        for k,v in o.items():
            find(v,path+'/'+k)
    elif isinstance(o,list):
        pass
    elif 'onnx_bytes' in path:
        print(path,o)
find(d)
" 2>/dev/null
done
